const segmentOf = (pathname: string) => {
  const value = pathname.split('/').filter(Boolean).at(-1)
  return !value || value === 'staff' || value === 'dashboard' ? 'dashboard' : value
}
const card = 'nexus-workspace-card principal-card rounded-2xl border border-gray-100 bg-white p-5 dark:border-kcs-blue-800 dark:bg-kcs-blue-900/50'
const button = 'rounded-xl bg-kcs-blue-700 px-4 py-2.5 text-sm font-semibold text-white hover:bg-kcs-blue-800 disabled:opacity-50'
const empty = (text: string) => <p className="rounded-xl bg-gray-50 p-5 text-sm text-gray-500 dark:bg-kcs-blue-800/30 dark:text-gray-300">{text}</p>
const personName = (value: any) => value?.fullName || [value?.firstName, value?.middleName, value?.lastName].filter(Boolean).join(' ') || 'Unidentified record'
const cleanClassName = (value: unknown) => {
  const raw = String(value ?? '').trim()
  const repeated = raw.match(/^(Grade\s+\d+)\s+\1$/i)
  if (repeated) return repeated[1]
  const parts = raw.split(/\s*[|/]\s*|\s{2,}/).filter(Boolean)
  return parts.filter((part,index)=>parts.findIndex((item)=>item.toLocaleLowerCase()===part.toLocaleLowerCase())===index).join(' / ') || '-'
}
const comparable = (value: unknown) => String(value ?? '').trim().toLocaleLowerCase().replace(/\s+/g,' ')
const downloadCsv = (filename: string, rows: unknown[][]) => {
  const body = rows.map((row) => row.map((cell) => '"' + String(cell ?? '').replace(/"/g, '""') + '"').join(',')).join('\n')
  const url = URL.createObjectURL(new Blob(['\uFEFF' + body], { type: 'text/csv;charset=utf-8' }))
  const link = document.createElement('a'); link.href = url; link.download = filename; link.click(); URL.revokeObjectURL(url)
}

const AdministratorMainTeacherAssignmentPanel = () => {
  const language = useUIStore((state) => state.language)
  const tr = (fr: string, en: string) => language === 'fr' ? fr : en
  const [teachers, setTeachers] = useState<any[]>([])
  const [drafts, setDrafts] = useState<Record<string, { status: 'HOMEROOM_TEACHER' | 'ASSISTANT_TEACHER' | 'TEACHER'; grade: string; section: string }>>({})
  const [busyId, setBusyId] = useState('')
  const [result, setResult] = useState<{ ok: boolean; message: string } | null>(null)
  const [teacherQuery, setTeacherQuery] = useState('')
  const name = (item: any) => [item.user?.lastName, item.user?.middleName, item.user?.firstName].filter(Boolean).join(' ')
  const filteredTeachers = useMemo(() => {
    const needle = teacherQuery.trim().toLocaleLowerCase()
    if (!needle) return teachers
    return teachers.filter((item) => [name(item), item.user?.email, item.homeroomGrade, item.homeroomSection].some((value) => String(value ?? '').toLocaleLowerCase().includes(needle)))
  }, [teachers, teacherQuery])
  const load = async () => {
    try {
      const response = await mainTeacherAPI.list()
      const rows = response.data?.data || []
      setTeachers(rows)
      setDrafts(Object.fromEntries(rows.map((item: any) => [item.id, {
        status: item.status || 'TEACHER',
        grade: item.homeroomGrade || SCHOOL_LEVELS[0],
        section: item.homeroomSection || '',
      }])))
    } catch (error: any) {
      setResult({ ok: false, message: error?.response?.data?.message || tr('Impossible de charger les enseignants.', 'Unable to load teachers.') })
    }
  }
  useEffect(() => { void load() }, [])
  const updateDraft = (id: string, patch: Partial<{ status: 'HOMEROOM_TEACHER' | 'ASSISTANT_TEACHER' | 'TEACHER'; grade: string; section: string }>) =>
    setDrafts((current) => ({ ...current, [id]: { ...(current[id] || { status: 'TEACHER', grade: SCHOOL_LEVELS[0], section: '' }), ...patch } }))
  const save = async (item: any) => {
    const draft = drafts[item.id]
    if (!draft) return
    setBusyId(item.id)
    try {
      await mainTeacherAPI.assign(item.id, {
        status: draft.status,
        homeroomGrade: draft.status === 'TEACHER' ? undefined : draft.grade,
        homeroomSection: draft.status === 'TEACHER' ? undefined : draft.section,
      })
      setResult({ ok: true, message: draft.status === 'HOMEROOM_TEACHER'
        ? tr(`${name(item)} est maintenant Main Teacher de ${draft.grade}${draft.section ? ' · ' + draft.section : ''}. Ses autres cours sont conservés.`, `${name(item)} is now the Main Teacher for ${draft.grade}${draft.section ? ' · ' + draft.section : ''}. Other courses remain unchanged.`)
        : draft.status === 'ASSISTANT_TEACHER'
          ? tr(`${name(item)} est maintenant Assistant Teacher de ${draft.grade}${draft.section ? ' · ' + draft.section : ''}.`, `${name(item)} is now the Assistant Teacher for ${draft.grade}${draft.section ? ' · ' + draft.section : ''}.`)
          : tr(`La responsabilité de classe de ${name(item)} a été retirée sans modifier ses cours ni son compte employé.`, `${name(item)}'s class responsibility was removed without changing courses or the employee account.`) })
      await load()
    } catch (error: any) {
      setResult({ ok: false, message: error?.response?.data?.message || tr('Affectation impossible.', 'Assignment failed.') })
    } finally { setBusyId('') }
  }
  return <div className="space-y-6">
    {result && <div className="fixed inset-0 z-[170] flex items-center justify-center bg-black/60 p-4" role="dialog" aria-modal="true"><div className="w-full max-w-lg rounded-2xl bg-white p-6 text-center shadow-2xl dark:bg-kcs-blue-950"><div className={'mx-auto flex h-14 w-14 items-center justify-center rounded-full text-2xl font-black text-white ' + (result.ok ? 'bg-emerald-600' : 'bg-red-600')}>{result.ok ? '✓' : '!'}</div><h3 className="mt-4 text-xl font-bold text-kcs-blue-950 dark:text-white">{result.ok ? tr('Opération réussie', 'Operation successful') : tr('Opération impossible', 'Operation failed')}</h3><p className="mt-2 text-sm text-slate-600 dark:text-slate-300">{result.message}</p><button type="button" onClick={() => setResult(null)} className="mt-5 w-full rounded-xl bg-kcs-blue-700 px-4 py-3 font-bold text-white">{tr('Fermer', 'Close')}</button></div></div>}
    <section className="rounded-2xl border border-sky-100 bg-sky-50/70 p-5 dark:border-kcs-blue-700 dark:bg-kcs-blue-900/60">
      <p className="text-xs font-black uppercase tracking-[0.16em] text-kcs-gold-600">{tr('Responsabilités de classe', 'Class responsibilities')}</p>
      <h2 className="mt-2 text-2xl font-bold text-kcs-blue-950 dark:text-white">{tr('Main Teachers et Assistants', 'Main Teachers and Assistants')}</h2>
      <p className="mt-2 max-w-4xl text-sm text-slate-600 dark:text-slate-300">{tr('Cochez directement le rôle de chaque enseignant, choisissez sa classe puis enregistrez. Un seul Main Teacher et un seul Assistant peuvent être affectés à une même classe. Les autres cours et le statut employé restent inchangés.', 'Check each teacher role directly, choose the class, then save. Each class accepts one Main Teacher and one Assistant. Other courses and employee status remain unchanged.')}</p>
      <div className="mt-4 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div className="flex flex-wrap gap-2 text-xs font-bold"><span className="rounded-full bg-blue-100 px-3 py-1.5 text-blue-800">{teachers.filter((item) => item.status === 'HOMEROOM_TEACHER').length} Main Teacher(s)</span><span className="rounded-full bg-amber-100 px-3 py-1.5 text-amber-800">{teachers.filter((item) => item.status === 'ASSISTANT_TEACHER').length} Assistant(s)</span><span className="rounded-full bg-emerald-100 px-3 py-1.5 text-emerald-800">{filteredTeachers.length} / {teachers.length} {tr('enseignants', 'teachers')}</span></div><label className="relative block w-full lg:max-w-md"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={17}/><input value={teacherQuery} onChange={(event) => setTeacherQuery(event.target.value)} className="w-full rounded-xl border border-sky-200 bg-white py-2.5 pl-10 pr-3 text-sm text-kcs-blue-950 outline-none focus:border-kcs-blue-500 focus:ring-2 focus:ring-kcs-blue-200 dark:border-kcs-blue-700 dark:bg-kcs-blue-950 dark:text-white" placeholder={tr('Rechercher par nom, e-mail, classe ou section', 'Search by name, email, class or section')}/></label></div>
    </section>
    <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white dark:border-kcs-blue-800 dark:bg-kcs-blue-900/50">
      <div className="grid grid-cols-[minmax(12rem,1.4fr)_minmax(9rem,.8fr)_minmax(9rem,.8fr)_minmax(8rem,.8fr)_minmax(7rem,.6fr)_auto] gap-3 border-b bg-slate-50 px-4 py-3 text-xs font-black uppercase tracking-wide text-slate-500 dark:border-kcs-blue-800 dark:bg-kcs-blue-950/60 dark:text-slate-300">
        <span>{tr('Employé / professeur', 'Employee / teacher')}</span><span>Main Teacher</span><span>{tr('Assistant', 'Assistant')}</span><span>{tr('Classe', 'Class')}</span><span>{tr('Section', 'Section')}</span><span>{tr('Action', 'Action')}</span>
      </div>
      <div className="divide-y dark:divide-kcs-blue-800">{filteredTeachers.map((item) => {
        const draft = drafts[item.id] || { status: 'TEACHER', grade: SCHOOL_LEVELS[0], section: '' }
        return <article key={item.id} className="grid grid-cols-1 gap-3 p-4 md:grid-cols-[minmax(12rem,1.4fr)_minmax(9rem,.8fr)_minmax(9rem,.8fr)_minmax(8rem,.8fr)_minmax(7rem,.6fr)_auto] md:items-center">
          <div><p className="font-bold text-kcs-blue-950 dark:text-white">{name(item)}</p><p className="text-xs text-slate-500">{item.user?.email} · {item._count?.courses || 0} {tr('cours', 'courses')}</p></div>
          <label className="flex items-center gap-2 text-sm font-semibold dark:text-white"><input type="checkbox" checked={draft.status === 'HOMEROOM_TEACHER'} onChange={(event) => updateDraft(item.id, { status: event.target.checked ? 'HOMEROOM_TEACHER' : 'TEACHER' })} className="h-5 w-5 accent-kcs-blue-700"/>Main Teacher</label>
          <label className="flex items-center gap-2 text-sm font-semibold dark:text-white"><input type="checkbox" checked={draft.status === 'ASSISTANT_TEACHER'} onChange={(event) => updateDraft(item.id, { status: event.target.checked ? 'ASSISTANT_TEACHER' : 'TEACHER' })} className="h-5 w-5 accent-amber-600"/>{tr('Assistant', 'Assistant')}</label>
          <select value={draft.grade} disabled={draft.status === 'TEACHER'} onChange={(event) => updateDraft(item.id, { grade: event.target.value })} className="rounded-xl border bg-white p-2.5 text-sm disabled:opacity-40 dark:border-kcs-blue-700 dark:bg-kcs-blue-950 dark:text-white">{SCHOOL_LEVELS.map((level) => <option key={level}>{level}</option>)}</select>
          <select value={draft.section} disabled={draft.status === 'TEACHER'} onChange={(event) => updateDraft(item.id, { section: event.target.value })} className="rounded-xl border bg-white p-2.5 text-sm disabled:opacity-40 dark:border-kcs-blue-700 dark:bg-kcs-blue-950 dark:text-white">{['', 'A', 'B', 'C', 'D'].map((value) => <option key={value || 'none'} value={value}>{value || tr('Sans section', 'No section')}</option>)}</select>
          <button type="button" disabled={busyId === item.id} onClick={() => void save(item)} className="rounded-xl bg-kcs-blue-700 px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50">{busyId === item.id ? tr('Enregistrement…', 'Saving…') : tr('Enregistrer', 'Save')}</button>
        </article>
      })}</div>
      {!filteredTeachers.length && <p className="p-8 text-center text-sm text-slate-500">{tr('Aucun professeur disponible.', 'No teacher is available.')}</p>}
    </section>
  </div>
}

const StaffPortal = () => {
  const { user } = useAuthStore()
  const language = useUIStore((state) => state.language)
  const location = useLocation()
  const segment = segmentOf(location.pathname)
  const isAdministrator = workspaceRole(user,location.pathname) === 'admin'
  const tr=(fr:string,en:string)=>language==='fr'?fr:en
  const [dashboardTab,setDashboardTab]=useState<'overview'|'community'>('overview')
  const [messageQuery,setMessageQuery]=useState('')
  const [directoryGrade,setDirectoryGrade]=useState('ALL'),[directoryPage,setDirectoryPage]=useState(1)
  const [reportTab,setReportTab]=useState<'workflow'|'teachers'>('workflow'),[messageTab,setMessageTab]=useState<'history'|'compose'>('history')
  const roleTitle = isAdministrator ? (language === 'fr' ? 'Principal' : 'Principal') : (language === 'fr' ? 'Personnel administratif' : 'Administrative Staff')
  const workspaceTitle = isAdministrator ? (language === 'fr' ? 'Centre opérationnel administrateur' : 'Administrator operations center') : (language === 'fr' ? 'Espace du personnel administratif' : 'Administrative Staff workspace')
  const basePath = isAdministrator ? '/admin' : '/portal/staff'
  const [overview, setOverview] = useState<any>({ stats: {}, attendanceByClass: [], applications: [], reportCards: [], announcements: [], recentActivity: [] })
  const [admissionRecords, setAdmissionRecords] = useState<any[]>([])
  const [admissionQuery, setAdmissionQuery] = useState('')
  const [admissionStatus, setAdmissionStatus] = useState('ALL')
  const [admissionNotes, setAdmissionNotes] = useState<Record<string, string>>({})
  const [announcementQuery, setAnnouncementQuery] = useState('')
  const [reportQuery, setReportQuery] = useState('')
  const [reportStatus, setReportStatus] = useState('ALL')
  const [financeQuery, setFinanceQuery] = useState('')
  const [financeClassFilter, setFinanceClassFilter] = useState('ALL')
  const [directory, setDirectory] = useState<any>({ students: [], parents: [], teachers: [], counts: {} })
  const [messages, setMessages] = useState<any[]>([])
  const [contacts, setContacts] = useState<any[]>([])
  const [finance, setFinance] = useState<any>(null)
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [notice, setNotice] = useState('')
  const [query, setQuery] = useState('')
  useEffect(()=>setDirectoryPage(1),[query,directoryGrade,segment])
  const [selected, setSelected] = useState<any>(null)
  const [selectedParent, setSelectedParent] = useState<any>(null)
  const [messageDraft, setMessageDraft] = useState({ recipientId: '', subject: '', body: '' })
  const [busy, setBusy] = useState(false)
  const [messageAttachment, setMessageAttachment] = useState<File | null>(null)

  const load = async () => {
    setStatus('loading')
    const results = await Promise.allSettled([
      adminAPI.getStaffOverview(),
      registryAPI.getDirectory().catch(() => registryAPI.getDirectory(true)),
      messagesAPI.getHistory({ box: 'all' }),
      messagesAPI.getContacts(),
      financeAPI.getEduPaySummary(),
      admissionsAPI.getAll(),
    ])
    if (results[0].status === 'fulfilled') setOverview(results[0].value.data?.data ?? {})
    if (results[1].status === 'fulfilled') {
      const next = results[1].value.data?.data ?? {}
      setDirectory((current: any) => {
        const currentCount = (current.students?.length ?? 0) + (current.parents?.length ?? 0)
        const nextCount = (next.students?.length ?? 0) + (next.parents?.length ?? 0)
        if (currentCount >= 10 && nextCount < Math.floor(currentCount * 0.7)) {
          setNotice(language === 'fr' ? 'Une chute anormale du registre Orbit a été bloquée; la dernière liste cohérente reste affichée.' : 'An abnormal Orbit directory drop was blocked; the last coherent list remains displayed.')
          return current
        }
        return next
      })
    }
    if (results[2].status === 'fulfilled') setMessages(results[2].value.data?.data ?? [])
    if (results[3].status === 'fulfilled') {
      const next = results[3].value.data?.data ?? []
      setContacts(next)
      setMessageDraft((draft) => ({ ...draft, recipientId: draft.recipientId || next[0]?.id || '' }))
    }
    if (results[4].status === 'fulfilled') setFinance(results[4].value.data?.data ?? null)
    if (results[5].status === 'fulfilled') setAdmissionRecords(results[5].value.data?.data ?? [])
    setStatus(results.slice(0, 4).some((result) => result.status === 'rejected') ? 'error' : 'ready')
  }

  useEffect(() => { void load() }, [])

  const students = directory.students ?? []
  const filteredStudents = useMemo(() => {
    const eligible=students.filter((student:any)=>directoryGrade==='ALL'||String(student.className||'').match(/^(K[345]|Grade\s*\d{1,2})/i)?.[0].replace(/Grade\s*/i,'Grade ')===directoryGrade)
    const needle = query.trim().toLowerCase()
    if (!needle) return [...eligible].sort((a: any, b: any) => cleanClassName(a.className).localeCompare(cleanClassName(b.className), undefined, { numeric: true }) || personName(a).localeCompare(personName(b)))
    return eligible.filter((student: any) => [personName(student), student.studentNumber, cleanClassName(student.className), student.email, student.phone, student.status].some((value) => comparable(value).includes(needle))).sort((a: any, b: any) => cleanClassName(a.className).localeCompare(cleanClassName(b.className), undefined, { numeric: true }) || personName(a).localeCompare(personName(b)))
  }, [students, query,directoryGrade])

  const parents = directory.parents ?? []
  const filteredParents = useMemo(() => {
    const matchesGrade=(parent:any)=>directoryGrade==='ALL'||students.some((student:any)=>(parent.studentIds?.includes(student.id)||student.parentId===parent.id)&&String(student.className||'').match(/^(K[345]|Grade\s*\d{1,2})/i)?.[0].replace(/Grade\s*/i,'Grade ')===directoryGrade)
    const needle = query.trim().toLowerCase()
    if (!needle) return parents.filter(matchesGrade).sort((a: any, b: any) => { const classOf=(parent:any)=>cleanClassName(students.find((student:any)=>parent.studentIds?.includes(student.id)||student.parentId===parent.id)?.className); return classOf(a).localeCompare(classOf(b), undefined, { numeric: true }) || personName(a).localeCompare(personName(b)) })
    return parents.filter(matchesGrade).filter((parent: any) => { const linked=students.filter((student:any)=>parent.studentIds?.includes(student.id)||student.parentId===parent.id); return [personName(parent),parent.email,parent.phone,parent.parentNumber,parent.displayId,...linked.flatMap((student:any)=>[personName(student),student.studentNumber,cleanClassName(student.className)])].some((value)=>comparable(value).includes(needle)) }).sort((a:any,b:any)=>personName(a).localeCompare(personName(b)))
  }, [parents, students, query,directoryGrade])

  const updateAdmission = async (id: string, nextStatus: 'UNDER_REVIEW' | 'INTERVIEW_SCHEDULED', notes?: string) => {
    setBusy(true); setNotice('')
    try {
      await admissionsAPI.updateStatus(id, nextStatus, notes)
      setOverview((current: any) => ({ ...current, applications: (current.applications ?? []).map((item: any) => item.id === id ? { ...item, status: nextStatus, notes } : item) }))
      setAdmissionRecords((current) => current.map((item) => item.id === id ? { ...item, status: nextStatus, notes } : item))
      setNotice(language === 'fr' ? 'L’étape et l’observation du Principal ont été enregistrées. La décision finale reste réservée à la Super Administration.' : 'The Principal stage and review note were saved. Final approval remains reserved for Super Administration.')
    } catch (error: any) { setNotice(error?.response?.data?.message ?? 'The admission stage could not be updated.') }
    finally { setBusy(false) }
  }

  const sendMessage = async () => {
    if (!messageDraft.recipientId || !messageDraft.subject.trim() || !messageDraft.body.trim()) return setNotice(tr('Choisissez un destinataire et complétez l’objet et le message.','Select a recipient and complete the subject and message.'))
    setBusy(true); setNotice('')
    try {
      const payload = new FormData(); payload.append("recipientId", messageDraft.recipientId); payload.append("subject", messageDraft.subject.trim()); payload.append("body", messageDraft.body.trim()); if (messageAttachment) payload.append("attachment", messageAttachment); const response = await messagesAPI.send(payload)
      setMessages((items) => [response.data?.data, ...items].filter(Boolean))
      setMessageDraft((draft) => ({ ...draft, subject: '', body: '' })); setMessageAttachment(null)
      setNotice('The internal message was sent and recorded.')
    } catch (error: any) { setNotice(error?.response?.data?.message ?? 'The message could not be sent.') }
    finally { setBusy(false) }
  }

  const parentById = new Map(parents.map((parent: any) => [parent.id, parent]))
  const currency = new Intl.NumberFormat(language === 'fr' ? 'fr-FR' : 'en-US', { style: 'currency', currency: 'USD' })
  const studentFinanceAccount = (student: any) => (finance?.studentAccounts ?? []).find((account: any) => comparable(account.studentId) === comparable(student.id) || comparable(account.studentNumber) === comparable(student.studentNumber) || comparable(account.studentName) === comparable(personName(student)))
  const parentFinanceAccount = (parent: any) => (finance?.parentAccounts ?? []).find((account: any) => comparable(account.parentId) === comparable(parent.id) || comparable(account.parentName) === comparable(personName(parent)) || comparable(account.email) === comparable(parent.email))
  const activeAdmissions = admissionRecords.length ? admissionRecords : (overview.applications ?? [])
  const filteredAdmissions = activeAdmissions.filter((item: any) => {
    if (admissionStatus !== 'ALL' && item.status !== admissionStatus) return false
    const children = Array.isArray(item.children) ? item.children : [item]
    return comparable([item.applicationNumber, item.parentName, item.parentEmail, item.parentPhone, item.status, ...children.flatMap((child: any) => [child.firstName, child.middleName, child.lastName, child.gradeApplying])].join(' ')).includes(comparable(admissionQuery))
  })
  const filteredAnnouncements = (overview.announcements ?? []).filter((item: any) => comparable([item.title, item.excerpt, item.category].join(' ')).includes(comparable(announcementQuery)))
  const filteredReportCards = (overview.reportCards ?? []).filter((item: any) => (reportStatus === 'ALL' || item.principalStatus === reportStatus || item.publicationStatus === reportStatus) && comparable([personName(item.student?.user), item.student?.studentNumber, item.term, item.principalStatus, item.publicationStatus].join(' ')).includes(comparable(reportQuery)))
  const financeAccounts = finance?.studentAccounts ?? []
  const financeClasses = [...new Set(financeAccounts.map((item: any) => String(item.className ?? '').trim()).filter(Boolean))].sort()
  const accountDebt = (item: any) => Number(item.debt ?? item.totalDebt ?? 0)
  const accountPaid = (item: any) => Number(item.paid ?? item.totalPaid ?? 0)
  const filteredFinanceAccounts = financeAccounts.filter((item: any) => (financeClassFilter === 'ALL' || item.className === financeClassFilter) && comparable([item.studentName, item.studentNumber, item.className, item.parentName, item.email].join(' ')).includes(comparable(financeQuery)))
  const pagedStudents=filteredStudents.slice((directoryPage-1)*12,directoryPage*12),pagedParents=filteredParents.slice((directoryPage-1)*12,directoryPage*12)
  const directoryTools=(count:number)=><div className="principal-directory-tools"><label>{tr('Classe','Class')}<select aria-label={tr('Filtrer le registre par classe','Filter registry by class')} value={directoryGrade} onChange={event=>setDirectoryGrade(event.target.value)}><option value="ALL">{tr('Toutes les classes','All classes')}</option>{SCHOOL_LEVELS.map(grade=><option key={grade}>{grade}</option>)}</select></label><span><b>{count}</b> {tr('résultat(s)','result(s)')}</span><button type="button" onClick={()=>{setQuery('');setDirectoryGrade('ALL');setDirectoryPage(1)}}>{tr('Réinitialiser les filtres','Reset filters')}</button></div>
  const directoryPager=(count:number)=><nav className="principal-pagination" aria-label={tr('Pages du registre','Registry pages')}><span>{tr('Page','Page')} {directoryPage} / {Math.max(1,Math.ceil(count/12))} · {tr('12 dossiers par page','12 records per page')}</span><div><button type="button" disabled={directoryPage<=1} onClick={()=>setDirectoryPage(page=>page-1)}>{tr('Précédent','Previous')}</button><button type="button" disabled={directoryPage>=Math.ceil(count/12)} onClick={()=>setDirectoryPage(page=>page+1)}>{tr('Suivant','Next')}</button></div></nav>
  const studentsView = <div className="space-y-6">
    <section className={card}>
      <div className="mb-4 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-kcs-blue-600">{language === 'fr' ? 'Registre officiel' : 'Official registry'}</p><h2 className="mt-1 text-2xl font-bold dark:text-white">{language === 'fr' ? 'Élèves' : 'Students'}</h2><p className="text-sm text-gray-500">{language === 'fr' ? 'Même tableau que la Super Administration, strictement en lecture seule.' : 'The same table as Super Administration, strictly read-only.'}</p></div><label className="relative block w-full lg:max-w-md"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16}/><input value={query} onChange={(event)=>setQuery(event.target.value)} className="w-full rounded-xl border py-2.5 pl-9 pr-3 text-sm dark:bg-kcs-blue-950" placeholder={language === 'fr' ? 'Nom, ID, classe, parent ou e-mail' : 'Name, ID, class, parent or email'}/></label></div>
      {directoryTools(filteredStudents.length)}<div className="overflow-x-auto"><table className="min-w-[980px] w-full text-sm"><thead className="bg-gray-50 text-left text-xs uppercase tracking-wide text-gray-500 dark:bg-kcs-blue-950 dark:text-gray-400"><tr><th className="px-5 py-3">Élève</th><th className="px-5 py-3">ID élève</th><th className="px-5 py-3">Classe</th><th className="px-5 py-3">{tr('Parent responsable','Responsible parent')}</th><th className="px-5 py-3">Contact</th><th className="px-5 py-3">{tr('Statut','Status')}</th><th className="px-5 py-3 text-right">Action</th></tr></thead><tbody className="divide-y dark:divide-kcs-blue-800">{pagedStudents.map((student:any)=>{const parent=parentById.get(student.parentId) as any;return <tr key={student.id} className="hover:bg-gray-50 dark:hover:bg-kcs-blue-800/20"><td className="px-5 py-4 font-semibold text-kcs-blue-900 dark:text-white">{personName(student)}</td><td className="px-5 py-4 font-mono text-xs">{student.studentNumber ?? '—'}</td><td className="px-5 py-4">{cleanClassName(student.className)}</td><td className="px-5 py-4">{parent ? personName(parent) : '—'}</td><td className="px-5 py-4 text-xs"><p>{parent?.email ?? student.email ?? '—'}</p><p className="mt-1">{parent?.phone ?? '—'}</p></td><td className="px-5 py-4"><span className="rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-bold text-emerald-700">{student.status ?? 'ACTIVE'}</span></td><td className="px-5 py-4 text-right"><button onClick={()=>setSelected(student)} className="rounded-lg border border-kcs-blue-300 bg-kcs-blue-50 px-3 py-2 text-xs font-bold text-kcs-blue-800 hover:bg-kcs-blue-100 dark:border-sky-400 dark:bg-sky-400 dark:text-kcs-blue-950 dark:hover:bg-sky-300">{language === 'fr' ? 'Voir' : 'View'}</button></td></tr>})}</tbody></table></div>{directoryPager(filteredStudents.length)}
      {filteredStudents.length===0&&empty(language === 'fr' ? 'Aucun élève ne correspond aux filtres.' : 'No student matches the filters.')}
    </section>
    {selected&&<PrincipalRecordDialog label={personName(selected)} onClose={()=>setSelected(null)}><section className="principal-record-dialog max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-3xl bg-white p-6 shadow-2xl dark:bg-kcs-blue-950" onClick={(event)=>event.stopPropagation()}><div className="flex justify-between gap-4"><div><p className="text-xs font-bold uppercase text-kcs-blue-600">{language==='fr'?'Consultation uniquement':'View only'}</p><h3 className="mt-2 text-2xl font-bold dark:text-white">{personName(selected)}</h3></div><button onClick={()=>setSelected(null)} className="rounded-xl border px-4 py-2 text-sm font-bold">{language==='fr'?'Fermer':'Close'}</button></div><div className="mt-6 grid gap-3 sm:grid-cols-2">{[['ID élève',selected.studentNumber],['E-mail scolaire',selected.email],['Classe',cleanClassName(selected.className)],['Statut',selected.status],['Parent responsable',parentById.get(selected.parentId)?personName(parentById.get(selected.parentId)):null],['Téléphone parent',(parentById.get(selected.parentId) as any)?.phone]].map(([label,value])=><div key={String(label)} className="rounded-xl bg-sky-50 p-4 dark:bg-kcs-blue-900"><p className="text-xs font-bold uppercase text-gray-400">{label}</p><p className="mt-2 break-words font-semibold dark:text-white">{value||'—'}</p></div>)}</div><div className="mt-5 rounded-2xl border border-amber-200 bg-amber-50 p-5 dark:border-amber-700/60 dark:bg-amber-950/30"><p className="text-xs font-black uppercase tracking-wider text-amber-700 dark:text-amber-300">{language==='fr'?'Situation financi\u00e8re EduPay':'EduPay financial profile'}</p><div className="mt-3 grid gap-3 sm:grid-cols-3"><div><p className="text-xs text-gray-500">{language==='fr'?'Classe':'Class'}</p><p className="font-bold dark:text-white">{cleanClassName(selected.className)}</p></div><div><p className="text-xs text-gray-500">{language==='fr'?'Pay\u00e9':'Paid'}</p><p className="font-bold text-emerald-700 dark:text-emerald-300">{currency.format(Number(studentFinanceAccount(selected)?.paid ?? studentFinanceAccount(selected)?.totalPaid ?? 0))}</p></div><div><p className="text-xs text-gray-500">{language==='fr'?'Reste \u00e0 payer':'Outstanding'}</p><p className="font-bold text-amber-700 dark:text-amber-300">{currency.format(Number(studentFinanceAccount(selected)?.debt ?? studentFinanceAccount(selected)?.totalDebt ?? 0))}</p></div></div></div><p className="mt-5 rounded-xl border border-sky-200 bg-sky-50 p-4 text-sm font-semibold text-kcs-blue-800 dark:border-kcs-blue-700 dark:bg-kcs-blue-900 dark:text-sky-100">{language==='fr'?'Aucune modification, suppression ou réinitialisation d’accès n’est autorisée dans cet espace Administrator.':'No edit, deletion or access reset is permitted in this Administrator workspace.'}</p></section></PrincipalRecordDialog>}
  </div>

  const parentsView = <div className="space-y-6">
    <section className={card}>
      <div className="mb-4 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-kcs-blue-600">{language === 'fr' ? 'Registre officiel' : 'Official registry'}</p><h2 className="mt-1 text-2xl font-bold dark:text-white">Parents</h2><p className="text-sm text-gray-500">{language === 'fr' ? 'Même tableau que la Super Administration, strictement en lecture seule.' : 'The same table as Super Administration, strictly read-only.'}</p></div><label className="relative block w-full lg:max-w-md"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={16}/><input value={query} onChange={(event)=>setQuery(event.target.value)} className="w-full rounded-xl border py-2.5 pl-9 pr-3 text-sm dark:bg-kcs-blue-950" placeholder={language === 'fr' ? 'Nom, email, téléphone ou identifiant' : 'Name, email, phone or identifier'}/></label></div>
      {directoryTools(filteredParents.length)}<div className="overflow-x-auto"><table className="min-w-[920px] w-full text-sm"><thead className="bg-gray-50 text-left text-xs uppercase tracking-wide text-gray-500 dark:bg-kcs-blue-950 dark:text-gray-400"><tr><th className="px-5 py-3">{tr('Parent responsable','Responsible parent')}</th><th className="px-5 py-3">{tr('Identifiant','Identifier')}</th><th className="px-5 py-3">{tr('Enfants liés','Linked children')}</th><th className="px-5 py-3">Contact</th><th className="px-5 py-3">{tr('Statut','Status')}</th><th className="px-5 py-3 text-right">Action</th></tr></thead><tbody className="divide-y dark:divide-kcs-blue-800">{pagedParents.map((parent:any)=>{const linked=students.filter((student:any)=>parent.studentIds?.includes(student.id)||student.parentId===parent.id);return <tr key={parent.id} className="hover:bg-gray-50 dark:hover:bg-kcs-blue-800/20"><td className="px-5 py-4 font-semibold text-kcs-blue-900 dark:text-white">{personName(parent)}</td><td className="px-5 py-4 font-mono text-xs">{parent.parentNumber ?? parent.displayId ?? '—'}</td><td className="px-5 py-4"><p className="font-bold">{linked.length}</p><p className="mt-1 max-w-xs truncate text-xs text-gray-500">{linked.map((student:any)=>personName(student)+' / '+cleanClassName(student.className)).join(', ')||'—'}</p></td><td className="px-5 py-4 text-xs"><p>{parent.email??'—'}</p><p className="mt-1">{parent.phone??'—'}</p></td><td className="px-5 py-4"><span className="rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-bold text-emerald-700">{linked.length?language==='fr'?'Actif':'Active':language==='fr'?'Sans enfant lié':'No linked child'}</span></td><td className="px-5 py-4 text-right"><button onClick={()=>setSelectedParent(parent)} className="rounded-lg border border-kcs-blue-300 bg-kcs-blue-50 px-3 py-2 text-xs font-bold text-kcs-blue-800 hover:bg-kcs-blue-100 dark:border-sky-400 dark:bg-sky-400 dark:text-kcs-blue-950 dark:hover:bg-sky-300">{language==='fr'?'Voir':'View'}</button></td></tr>})}</tbody></table></div>{directoryPager(filteredParents.length)}
      {filteredParents.length===0&&empty(language === 'fr' ? 'Aucun parent ne correspond aux filtres.' : 'No parent matches the filters.')}
    </section>
    {selectedParent&&<PrincipalRecordDialog label={personName(selectedParent)} onClose={()=>setSelectedParent(null)}><section className="principal-record-dialog max-h-[92vh] w-full max-w-4xl overflow-y-auto rounded-3xl bg-white p-6 shadow-2xl dark:bg-kcs-blue-950" onClick={(event)=>event.stopPropagation()}><div className="flex justify-between gap-4"><div><p className="text-xs font-bold uppercase text-kcs-blue-600">{language==='fr'?'Consultation uniquement':'View only'}</p><h3 className="mt-2 text-2xl font-bold dark:text-white">{personName(selectedParent)}</h3></div><button onClick={()=>setSelectedParent(null)} className="rounded-xl border px-4 py-2 text-sm font-bold">{language==='fr'?'Fermer':'Close'}</button></div><div className="mt-6 grid gap-3 sm:grid-cols-2">{[['E-mail',selectedParent.email],['Téléphone',selectedParent.phone],['Identifiant',selectedParent.parentNumber??selectedParent.displayId],['Enfants liés',students.filter((student:any)=>selectedParent.studentIds?.includes(student.id)||student.parentId===selectedParent.id).map((student:any)=>personName(student)+' / '+cleanClassName(student.className)).join(', ')]].map(([label,value])=><div key={String(label)} className="rounded-xl bg-sky-50 p-4 dark:bg-kcs-blue-900"><p className="text-xs font-bold uppercase text-gray-400">{label}</p><p className="mt-2 break-words font-semibold dark:text-white">{value||'—'}</p></div>)}</div><div className="mt-5 rounded-2xl border border-amber-200 bg-amber-50 p-5 dark:border-amber-700/60 dark:bg-amber-950/30"><p className="text-xs font-black uppercase tracking-wider text-amber-700 dark:text-amber-300">{language==='fr'?'Suivi financier familial EduPay':'EduPay family finance tracking'}</p><div className="mt-3 grid gap-3 sm:grid-cols-3"><div><p className="text-xs text-gray-500">{language==='fr'?'\u00c9l\u00e8ves li\u00e9s':'Linked students'}</p><p className="font-bold dark:text-white">{students.filter((student:any)=>selectedParent.studentIds?.includes(student.id)||student.parentId===selectedParent.id).length}</p></div><div><p className="text-xs text-gray-500">{language==='fr'?'Pay\u00e9':'Paid'}</p><p className="font-bold text-emerald-700 dark:text-emerald-300">{currency.format(Number(parentFinanceAccount(selectedParent)?.totalPaid ?? 0))}</p></div><div><p className="text-xs text-gray-500">{language==='fr'?'Reste \u00e0 payer':'Outstanding'}</p><p className="font-bold text-amber-700 dark:text-amber-300">{currency.format(Number(parentFinanceAccount(selectedParent)?.totalDebt ?? 0))}</p></div></div></div><p className="mt-5 rounded-xl border border-sky-200 bg-sky-50 p-4 text-sm font-semibold text-kcs-blue-800 dark:border-kcs-blue-700 dark:bg-kcs-blue-900 dark:text-sky-100">{language==='fr'?'Aucune modification, suppression, blocage ou réinitialisation d’accès n’est autorisée dans cet espace Administrator.':'No edit, deletion, blocking or access reset is permitted in this Administrator workspace.'}</p></section></PrincipalRecordDialog>}
  </div>

  const admissionsView = <div className="space-y-6">
    <section className={card}><div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><p className="text-xs font-black uppercase tracking-[.18em] text-kcs-gold-600">{language==='fr'?'Admissions en ligne · workflow partagé':'Online admissions · shared workflow'}</p><h2 className="mt-2 text-2xl font-black text-kcs-blue-950 dark:text-white">{language==='fr'?'Centre de revue du Principal':'Principal review center'}</h2><p className="mt-2 max-w-4xl text-sm text-slate-600 dark:text-slate-300">{language==='fr'?'Toutes les demandes soumises en ligne sont visibles ici et chez la Super Administration. Le Principal vérifie le dossier, consigne son observation et programme l’entretien; la décision finale et la création des comptes restent réservées à la Super Administration.':'Every online submission is visible here and in Super Administration. The Principal reviews the file, records an observation and schedules the interview; final approval and account provisioning remain reserved for Super Administration.'}</p></div><button type="button" onClick={()=>void load()} className={button}>{language==='fr'?'Actualiser la file':'Refresh queue'}</button></div><div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-5">{[[language==='fr'?'Total':'Total',activeAdmissions.length],[language==='fr'?'Soumises':'Submitted',activeAdmissions.filter((x:any)=>x.status==='SUBMITTED').length],[language==='fr'?'En revue':'Under review',activeAdmissions.filter((x:any)=>x.status==='UNDER_REVIEW').length],[language==='fr'?'Entretiens':'Interviews',activeAdmissions.filter((x:any)=>x.status==='INTERVIEW_SCHEDULED').length],[language==='fr'?'Finalisées':'Finalized',activeAdmissions.filter((x:any)=>['ACCEPTED','REJECTED'].includes(x.status)).length]].map(([label,value])=><div key={String(label)} className="rounded-xl bg-white p-4 dark:bg-kcs-blue-950/40"><p className="text-2xl font-black dark:text-white">{value}</p><p className="text-xs font-bold uppercase text-slate-500">{label}</p></div>)}</div></section>
    <section className={card}><div className="grid gap-3 lg:grid-cols-[1fr_16rem]"><label className="relative"><Search className="absolute left-3 top-3 text-slate-400" size={17}/><input value={admissionQuery} onChange={(event)=>setAdmissionQuery(event.target.value)} className="w-full rounded-xl border border-sky-200 bg-white py-2.5 pl-10 pr-3 text-sm dark:border-kcs-blue-700 dark:bg-kcs-blue-950 dark:text-white" placeholder={language==='fr'?'Candidat, parent, e-mail, numéro ou classe':'Candidate, parent, email, number or grade'}/></label><select value={admissionStatus} onChange={(event)=>setAdmissionStatus(event.target.value)} className="rounded-xl border border-sky-200 bg-white px-3 py-2.5 text-sm dark:border-kcs-blue-700 dark:bg-kcs-blue-950 dark:text-white"><option value="ALL">{language==='fr'?'Tous les statuts':'All statuses'}</option>{['SUBMITTED','UNDER_REVIEW','INTERVIEW_SCHEDULED','WAITLISTED','ACCEPTED','REJECTED'].map(value=><option key={value}>{value}</option>)}</select></div><div className="mt-5 grid gap-4 xl:grid-cols-2">{filteredAdmissions.map((item:any)=>{const children=Array.isArray(item.children)&&item.children.length?item.children:[item];return <article key={item.id} className="rounded-2xl border border-sky-100 bg-white p-5 dark:border-kcs-blue-700 dark:bg-kcs-blue-950/50"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs font-black text-kcs-gold-600">{item.applicationNumber}</p><h3 className="mt-1 font-black text-kcs-blue-950 dark:text-white">{children.map((child:any)=>personName(child)).join(' · ')}</h3><p className="text-sm text-slate-500">{item.parentName} · {item.parentEmail}</p></div><span className="rounded-full bg-sky-100 px-3 py-1 text-xs font-bold text-sky-800 dark:bg-kcs-blue-800 dark:text-sky-100">{String(item.status).replace(/_/g,' ')}</span></div><div className="mt-3 flex flex-wrap gap-2">{children.map((child:any,index:number)=><span key={index} className="rounded-lg bg-sky-50 px-3 py-2 text-xs font-bold dark:bg-kcs-blue-900 dark:text-white">{personName(child)} · {child.gradeApplying||item.gradeApplying}</span>)}</div><label className="mt-4 block text-xs font-bold text-slate-600 dark:text-slate-300">{language==='fr'?'Observation académique du Principal':'Principal academic review note'}<textarea value={admissionNotes[item.id]??item.notes??''} onChange={(event)=>setAdmissionNotes((current)=>({...current,[item.id]:event.target.value}))} className="mt-1 min-h-24 w-full rounded-xl border border-sky-200 bg-white p-3 text-sm dark:border-kcs-blue-700 dark:bg-kcs-blue-950 dark:text-white" placeholder={language==='fr'?'Pièces vérifiées, niveau demandé, entretien, réserves…':'Documents checked, requested level, interview, concerns…'}/></label><div className="mt-4 grid gap-2 sm:grid-cols-2"><button disabled={busy} onClick={()=>void updateAdmission(item.id,'UNDER_REVIEW',admissionNotes[item.id]??item.notes)} className="rounded-xl border border-sky-200 px-4 py-2.5 text-sm font-bold dark:border-kcs-blue-700">{language==='fr'?'Marquer en revue':'Mark under review'}</button><button disabled={busy} onClick={()=>void updateAdmission(item.id,'INTERVIEW_SCHEDULED',admissionNotes[item.id]??item.notes)} className={button}>{language==='fr'?'Programmer l’entretien':'Schedule interview'}</button></div></article>})}</div>{!filteredAdmissions.length&&empty(language==='fr'?'Aucune demande ne correspond aux filtres.':'No application matches the filters.')}</section>
  </div>

  const announcementsView = <div className="space-y-6"><section className={card}><p className="text-xs font-black uppercase tracking-[.18em] text-kcs-gold-600">{language==='fr'?'Communication institutionnelle':'Institutional communication'}</p><h2 className="mt-2 text-2xl font-black text-kcs-blue-950 dark:text-white">{language==='fr'?'Annonces officielles':'Official announcements'}</h2><p className="mt-2 text-sm text-slate-600 dark:text-slate-300">{language==='fr'?'Historique consultable et filtrable des annonces publiées. Le canal Messages reste disponible pour les communications opérationnelles ciblées.':'Searchable, filterable history of published announcements. Messages remains available for targeted operational communication.'}</p></section><section className={card}><label className="relative block max-w-2xl"><Search className="absolute left-3 top-3 text-slate-400" size={17}/><input value={announcementQuery} onChange={(event)=>setAnnouncementQuery(event.target.value)} className="w-full rounded-xl border border-sky-200 bg-white py-2.5 pl-10 pr-3 text-sm dark:border-kcs-blue-700 dark:bg-kcs-blue-950 dark:text-white" placeholder={language==='fr'?'Titre, résumé ou catégorie':'Title, summary or category'}/></label><div className="principal-history-scroll mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{filteredAnnouncements.map((item:any)=><article key={item.id} className="rounded-2xl border border-sky-100 bg-white p-5 dark:border-kcs-blue-700 dark:bg-kcs-blue-950/40"><div className="flex items-start justify-between gap-3"><Megaphone className="text-kcs-blue-600" size={19}/><span className="rounded-full bg-sky-100 px-2.5 py-1 text-xs font-bold text-sky-800">{item.category}</span></div><h3 className="mt-3 font-black text-kcs-blue-950 dark:text-white">{item.title}</h3><p className="mt-2 text-sm text-slate-600 dark:text-slate-300">{item.excerpt}</p><p className="mt-3 text-xs text-slate-400">{new Date(item.publishedAt).toLocaleString()}</p></article>)}</div>{!filteredAnnouncements.length&&empty(language==='fr'?'Aucune annonce ne correspond à cette recherche.':'No announcement matches this search.')}</section></div>

  const reportsView = <div className="space-y-6"><section className={card}><div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><p className="text-xs font-black uppercase tracking-[.18em] text-kcs-gold-600">{language==='fr'?'Gouvernance académique':'Academic governance'}</p><h2 className="mt-2 text-2xl font-black text-kcs-blue-950 dark:text-white">{language==='fr'?'Suivi des report cards':'Report-card workflow'}</h2><p className="mt-2 text-sm text-slate-600 dark:text-slate-300">{language==='fr'?'Suivi réel de la soumission du Main Teacher, de la revue pédagogique et de la publication par la Super Administration.':'Real tracking of Main Teacher submission, academic review and Super Administration publication.'}</p></div><button onClick={()=>downloadCsv('principal-report-card-workflow.csv',[[language==='fr'?'Élève':'Student','ID','Term',language==='fr'?'Moyenne':'Average',language==='fr'?'Revue':'Review','Publication'],...filteredReportCards.map((item:any)=>[personName(item.student?.user),item.student?.studentNumber,item.term,item.average,item.principalStatus,item.publicationStatus])])} className="rounded-xl border border-sky-200 bg-white px-4 py-2.5 text-sm font-bold text-kcs-blue-800 dark:border-kcs-blue-700 dark:bg-kcs-blue-950 dark:text-white">{tr('Exporter CSV','Export CSV')}</button></div><div className="mt-5 grid gap-3 sm:grid-cols-3">{[[language==='fr'?'Dossiers':'Records',(overview.reportCards??[]).length],[language==='fr'?'À revoir':'Pending review',(overview.reportCards??[]).filter((x:any)=>x.principalStatus!=='APPROVED').length],[language==='fr'?'Publiés':'Published',(overview.reportCards??[]).filter((x:any)=>['EMAILED','POSTED_TO_PORTAL'].includes(x.publicationStatus)).length]].map(([label,value])=><div key={String(label)} className="rounded-xl bg-white p-4 dark:bg-kcs-blue-950/40"><p className="text-2xl font-black dark:text-white">{value}</p><p className="text-xs font-bold uppercase text-slate-500">{label}</p></div>)}</div></section><section className={card}><div className="grid gap-3 md:grid-cols-[1fr_15rem]"><input value={reportQuery} onChange={(event)=>setReportQuery(event.target.value)} className="rounded-xl border border-sky-200 bg-white px-3 py-2.5 text-sm dark:border-kcs-blue-700 dark:bg-kcs-blue-950 dark:text-white" placeholder={language==='fr'?'Élève, ID, période ou statut':'Student, ID, term or status'}/><select value={reportStatus} onChange={(event)=>setReportStatus(event.target.value)} className="rounded-xl border border-sky-200 bg-white px-3 py-2.5 text-sm dark:border-kcs-blue-700 dark:bg-kcs-blue-950 dark:text-white"><option value="ALL">{language==='fr'?'Tous les statuts':'All statuses'}</option>{['SUBMITTED','APPROVED','POSTED_TO_PORTAL','EMAILED'].map(value=><option key={value}>{value}</option>)}</select></div><div className="mt-4 overflow-x-auto"><table className="min-w-[760px] w-full text-sm"><thead><tr className="border-b text-left text-xs uppercase text-slate-500"><th className="p-3">{language==='fr'?'Élève':'Student'}</th><th className="p-3">{language==='fr'?'Période':'Term'}</th><th className="p-3">{language==='fr'?'Moyenne':'Average'}</th><th className="p-3">{language==='fr'?'Revue':'Review'}</th><th className="p-3">Publication</th></tr></thead><tbody>{filteredReportCards.map((item:any)=><tr key={item.id} className="border-b border-sky-100 dark:border-kcs-blue-800"><td className="p-3 font-bold dark:text-white">{personName(item.student?.user)}<small className="block font-normal text-slate-400">{item.student?.studentNumber}</small></td><td className="p-3">{item.term}</td><td className="p-3">{item.average??'—'}{item.average!=null?'%':''}</td><td className="p-3">{item.principalStatus}</td><td className="p-3">{item.publicationStatus}</td></tr>)}</tbody></table></div>{!filteredReportCards.length&&empty(language==='fr'?'Aucun report card ne correspond aux filtres.':'No report card matches the filters.')}</section></div>

  const financeView = !finance?<section className={card}>{empty(language==='fr'?'La synchronisation EduPay est momentanément indisponible.':'EduPay synchronization is temporarily unavailable.')}</section>:<div className="space-y-6"><section className={card}><div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><p className="text-xs font-black uppercase tracking-[.18em] text-kcs-gold-600">EduPay · {language==='fr'?'lecture seule':'read only'}</p><h2 className="mt-2 text-2xl font-black text-kcs-blue-950 dark:text-white">{language==='fr'?'Pilotage des obligations financières':'Financial obligations monitoring'}</h2><p className="mt-2 text-sm text-slate-600 dark:text-slate-300">{language==='fr'?'Le Principal suit les soldes utiles à la scolarité, sans pouvoir enregistrer, modifier ou annuler un paiement.':'The Principal monitors school-related balances without permission to record, edit or reverse a payment.'}</p></div><button onClick={()=>downloadCsv('principal-edupay-read-only.csv',[[language==='fr'?'Élève':'Student','ID',language==='fr'?'Classe':'Class',language==='fr'?'Payé':'Paid',language==='fr'?'Reste':'Outstanding'],...filteredFinanceAccounts.map((item:any)=>[item.studentName,item.studentNumber,item.className,accountPaid(item),accountDebt(item)])])} className="rounded-xl border border-sky-200 bg-white px-4 py-2.5 text-sm font-bold text-kcs-blue-800 dark:border-kcs-blue-700 dark:bg-kcs-blue-950 dark:text-white">{language==='fr'?'Exporter la vue':'Export view'}</button></div><div className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[[language==='fr'?'Comptes visibles':'Visible accounts',financeAccounts.length],[language==='fr'?'Soldes ouverts':'Open balances',financeAccounts.filter((item:any)=>accountDebt(item)>0).length],[language==='fr'?'Comptes à jour':'Cleared accounts',financeAccounts.filter((item:any)=>accountDebt(item)<=0).length],[language==='fr'?'Reste total':'Total outstanding',currency.format(financeAccounts.reduce((sum:number,item:any)=>sum+accountDebt(item),0))]].map(([label,value])=><div key={String(label)} className="rounded-xl bg-white p-4 dark:bg-kcs-blue-950/40"><p className="text-2xl font-black dark:text-white">{value}</p><p className="text-xs font-bold uppercase text-slate-500">{label}</p></div>)}</div></section><section className={card}><div className="grid gap-3 md:grid-cols-[1fr_16rem]"><input value={financeQuery} onChange={(event)=>setFinanceQuery(event.target.value)} className="rounded-xl border border-sky-200 bg-white px-3 py-2.5 text-sm dark:border-kcs-blue-700 dark:bg-kcs-blue-950 dark:text-white" placeholder={language==='fr'?'Élève, parent, ID ou classe':'Student, parent, ID or class'}/><select value={financeClassFilter} onChange={(event)=>setFinanceClassFilter(event.target.value)} className="rounded-xl border border-sky-200 bg-white px-3 py-2.5 text-sm dark:border-kcs-blue-700 dark:bg-kcs-blue-950 dark:text-white"><option value="ALL">{language==='fr'?'Toutes les classes':'All classes'}</option>{financeClasses.map((value:any)=><option key={value}>{value}</option>)}</select></div><div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{filteredFinanceAccounts.map((account:any,index:number)=><article key={account.studentId??account.studentNumber??index} className="rounded-xl border border-sky-100 bg-white p-4 dark:border-kcs-blue-700 dark:bg-kcs-blue-950/40"><div className="flex justify-between gap-3"><div><p className="font-black dark:text-white">{account.studentName||(language==='fr'?'Compte élève':'Student account')}</p><p className="text-xs text-slate-500">{account.studentNumber||'—'} · {account.className||'—'}</p></div>{accountDebt(account)>0?<span className="text-amber-500">●</span>:<span className="text-emerald-500">●</span>}</div><div className="mt-3 grid grid-cols-2 gap-2 text-sm"><p className="rounded-lg bg-emerald-50 p-3">{language==='fr'?'Payé':'Paid'}<b className="block text-emerald-700">{currency.format(accountPaid(account))}</b></p><p className="rounded-lg bg-amber-50 p-3">{language==='fr'?'Reste':'Outstanding'}<b className="block text-amber-700">{currency.format(accountDebt(account))}</b></p></div></article>)}</div>{!filteredFinanceAccounts.length&&empty(language==='fr'?'Aucun compte ne correspond aux filtres.':'No account matches the filters.')}</section></div>

  const messagesView = <div className="space-y-5"><nav className="principal-tabs" aria-label={tr('Rubriques des messages','Message sections')}>{([['history',tr('Historique des échanges','Conversation history')],['compose',tr('Nouveau message','New message')]] as const).map(([key,label])=><button type="button" key={key} aria-pressed={messageTab===key} onClick={()=>setMessageTab(key)}><MessageSquare size={17}/>{label}</button>)}</nav><div hidden={messageTab!=='history'}><section className={card}><h2 className="font-bold dark:text-white">{tr('Historique des messages','Message history')}</h2><label className="principal-message-search"><Search size={17}/><input type="search" value={messageQuery} onChange={event=>setMessageQuery(event.target.value)} aria-label={tr('Rechercher dans les messages','Search messages')} placeholder={tr('Objet, message ou date…','Subject, message or date…')}/></label>{messages.length===0?empty(tr('Aucun message interne.','No internal message.')):<div className="principal-message-history mt-4 space-y-3">{messages.filter(item=>comparable([item.subject,item.body,new Date(item.createdAt).toLocaleString(language==='fr'?'fr-FR':'en-GB')].join(' ')).includes(comparable(messageQuery))).map((item:any)=><article key={item.id} className="rounded-xl bg-gray-50 p-4 dark:bg-kcs-blue-800/30"><h3 className="font-semibold dark:text-white">{item.subject}</h3><p className="mt-1 text-sm text-gray-600 dark:text-gray-300">{item.body}</p><MessageAttachment message={item} compact/><p className="mt-2 text-xs text-gray-400">{new Date(item.createdAt).toLocaleString()}</p></article>)}</div>}</section></div><div hidden={messageTab!=='compose'}><section className={card}><h2 className="font-bold dark:text-white">{tr('Rédiger un message ciblé','Compose a targeted message')}</h2><div className="mt-4 grid gap-3"><label className="principal-field-label">{tr('Destinataire','Recipient')}<select value={messageDraft.recipientId} onChange={(event)=>setMessageDraft({...messageDraft,recipientId:event.target.value})} className="rounded-xl border bg-white p-3 dark:bg-kcs-blue-950">{contacts.map((contact:any)=><option key={contact.id} value={contact.id}>{personName(contact)} · {contact.role}</option>)}</select></label><label className="principal-field-label">{tr('Objet','Subject')}<input value={messageDraft.subject} onChange={(event)=>setMessageDraft({...messageDraft,subject:event.target.value})} className="rounded-xl border p-3 dark:bg-kcs-blue-950" placeholder={tr('Objet de votre message','Message subject')}/></label><label className="principal-field-label">{tr('Message','Message')}<textarea value={messageDraft.body} onChange={(event)=>setMessageDraft({...messageDraft,body:event.target.value})} className="min-h-36 rounded-xl border p-3 dark:bg-kcs-blue-950" placeholder={tr('Écrivez votre message…','Write your message…')}/></label><label className="flex cursor-pointer items-center justify-center rounded-xl border border-dashed border-kcs-blue-300 p-3 text-sm font-semibold dark:text-sky-200">{messageAttachment?.name || (language === "fr" ? "Joindre un audio, une vidéo, une image ou un document" : "Attach audio, video, image or document")}<input type="file" className="sr-only" accept="image/*,audio/*,video/mp4,video/webm,video/quicktime,.pdf,.doc,.docx,.xls,.xlsx,.txt,.csv" onChange={(event)=>{const file=event.target.files?.[0]||null;if(file&&file.size>25*1024*1024){setNotice(language === "fr" ? "Le fichier ne doit pas dépasser 25 Mo." : "The file must not exceed 25 MB.");return}setMessageAttachment(file)}}/></label><AudioRecorder language={language} disabled={busy} onRecorded={setMessageAttachment}/><button disabled={busy} onClick={()=>void sendMessage()} className={button}>{busy?tr('Envoi…','Sending…'):tr('Envoyer et enregistrer','Send and record')}</button></div></section></div></div>

  const permissionsView = <div className="grid gap-6 xl:grid-cols-[1.05fr_.95fr]"><section className={card}><p className="text-xs font-black uppercase tracking-[.18em] text-kcs-gold-600">RBAC</p><h2 className="mt-2 text-2xl font-black text-kcs-blue-950 dark:text-white">{isAdministrator?tr('Matrice d’autorisation du Principal','Principal permission matrix'):tr('Matrice d’autorisation du Staff','Staff permission matrix')}</h2><p className="mt-2 text-sm text-slate-600 dark:text-slate-300">{language==='fr'?'Les responsabilités pédagogiques sont actives; les opérations irréversibles restent sous contrôle de la Super Administration.':'Academic responsibilities are enabled; irreversible operations remain under Super Administration control.'}</p><div className="mt-5 space-y-3">{[[language==='fr'?'Registres élèves et parents':'Student and parent records',true,language==='fr'?'Consultation seulement':'Read only'],[language==='fr'?'Revue académique des admissions':'Academic admission review',true,language==='fr'?'Revue et entretien':'Review and interview'],[language==='fr'?'Annonces institutionnelles':'Institutional announcements',true,language==='fr'?'Consultation et communication':'Review and communication'],['Report cards',true,language==='fr'?'Suivi du workflow':'Workflow monitoring'],[language==='fr'?'Soldes EduPay':'EduPay balances',true,language==='fr'?'Consultation seulement':'Read only'],[language==='fr'?'Création/suppression de comptes':'Account provisioning/deletion',false,language==='fr'?'Réservé à la Super Administration':'Reserved for Super Administration'],[language==='fr'?'Validation finale et transcripts':'Final approval and transcripts',false,language==='fr'?'Réservé à la Super Administration':'Reserved for Super Administration']].map(([label,allowed,detail])=><div key={String(label)} className="flex items-center justify-between gap-4 rounded-xl bg-white p-4 dark:bg-kcs-blue-950/40"><span className="font-bold text-kcs-blue-950 dark:text-white">{allowed?'✓':'🔒'} {label}</span><span className="text-right text-xs font-bold text-slate-500">{detail}</span></div>)}</div></section><section className={card}><h2 className="font-black text-kcs-blue-950 dark:text-white">{language==='fr'?'Journal de mes actions':'My audit activity'}</h2><p className="mb-4 text-xs text-slate-500">{language==='fr'?'Traçabilité personnelle, sans altération possible.':'Personal traceability, tamper-proof.'}</p>{(overview.recentActivity??[]).length===0?empty(language==='fr'?'Aucune action administrative récente.':'No recent administrative action.'):<div className="principal-history-scroll space-y-3">{overview.recentActivity.map((item:any)=><div key={item.id} className="rounded-xl bg-white p-4 text-sm dark:bg-kcs-blue-950/40"><b className="dark:text-white">{item.action}</b><p className="text-xs text-slate-500">{item.targetType} · {new Date(item.createdAt).toLocaleString()}</p></div>)}</div>}</section></div>

  const dashboardOverview = <><AdminOperationsPanel isAdministrator={isAdministrator} basePath={basePath} overview={overview} language={language}/><div className="grid grid-cols-2 gap-4 xl:grid-cols-5">{[
    [tr('Élèves du registre','Student records'),directory.counts?.students??students.length,Users,tr('Registre Orbit partagé','Shared Orbit registry')],
    [tr('Familles','Families'),directory.counts?.families??0,Users,tr('Familles responsables','Responsible families')],
    [tr('Messages en attente','Pending messages'),overview.stats?.pendingMessages??0,MessageSquare,tr('Messages internes non lus','Unread internal messages')],
    [tr('Admissions à traiter','Admission tasks'),overview.stats?.admissionTasks??0,ClipboardList,tr('Revue ou entretien','Review or interview')],
    [tr('Rapports en attente','Pending reports'),overview.stats?.pendingReports??0,ShieldCheck,tr('Suivi opérationnel','Operational follow-up')],
  ].map(([label,value,Icon,sub]:any)=><motion.div key={label} initial={{opacity:0,y:12}} animate={{opacity:1,y:0}} className={card}><Icon className="text-kcs-blue-600" size={20}/><p className="mt-3 text-3xl font-bold dark:text-white">{value}</p><p className="text-sm font-semibold dark:text-gray-200">{label}</p><p className="text-xs text-gray-400">{sub}</p></motion.div>)}</div>
  <div className="grid gap-6 xl:grid-cols-[1.2fr_.8fr]"><section className={card}><h2 className="font-bold dark:text-white">{tr('Présences enregistrées par classe','Recorded attendance by class')}</h2>{(overview.attendanceByClass??[]).length===0?empty(tr('Les indicateurs apparaîtront après l’enregistrement des présences.','Attendance indicators will appear after records are entered.')):<ResponsiveContainer width="100%" height={280}><BarChart data={overview.attendanceByClass}><CartesianGrid strokeDasharray="3 3"/><XAxis dataKey="label"/><YAxis domain={[0,100]}/><Tooltip/><Bar dataKey="attendance" fill="#1d4ed8" radius={[7,7,0,0]}/></BarChart></ResponsiveContainer>}</section><section className={card}><h2 className="font-bold dark:text-white">{tr('Priorités administratives','Administrative workload')}</h2><div className="mt-4 space-y-3">{[[ClipboardList,'Admissions',overview.stats?.admissionTasks??0],[MessageSquare,'Messages',overview.stats?.pendingMessages??0],[FileText,'Reports',overview.stats?.pendingReports??0],[ShieldCheck,'Open incidents',overview.stats?.openIncidents??0]].map(([Icon,label,value]:any)=><Link key={label} to={label==='Admissions'?basePath+'/admissions':label==='Messages'?basePath+'/messages':label==='Reports'?basePath+'/reports':basePath+'/permissions'} className="flex items-center justify-between rounded-xl bg-gray-50 p-4 dark:bg-kcs-blue-800/30"><span className="flex items-center gap-3 font-semibold dark:text-white"><Icon size={18}/>{label}</span><b>{value}</b></Link>)}</div></section></div>
  <div className="grid gap-6 xl:grid-cols-3"><section className={card}><h2 className="flex items-center gap-2 font-bold dark:text-white"><ClipboardList size={18}/>{tr('Admissions récentes','Recent admissions')}</h2><div className="mt-4 space-y-3">{(overview.applications??[]).slice(0,5).map((item:any)=><div key={item.id} className="rounded-xl bg-gray-50 p-3 dark:bg-kcs-blue-800/30"><b className="dark:text-white">{[item.firstName,item.lastName].join(' ')}</b><p className="text-xs text-gray-500">{item.gradeApplying} · {String(item.status).replace(/_/g,' ')}</p></div>)}</div></section><section className={card}><h2 className="flex items-center gap-2 font-bold dark:text-white"><Bell size={18}/>{tr('Annonces','Announcements')}</h2><div className="mt-4 space-y-3">{(overview.announcements??[]).slice(0,5).map((item:any)=><div key={item.id} className="rounded-xl bg-gray-50 p-3 dark:bg-kcs-blue-800/30"><b className="dark:text-white">{item.title}</b><p className="text-xs text-gray-500">{new Date(item.publishedAt).toLocaleDateString()}</p></div>)}</div></section><section className={card}><h2 className="flex items-center gap-2 font-bold dark:text-white"><WalletCards size={18}/>{tr('Situation EduPay','EduPay status')}</h2>{finance?<div className="mt-4 space-y-2"><p className="text-3xl font-bold dark:text-white">{finance.totals?.paymentCompletionRate??0}%</p><p className="text-sm text-gray-500">{tr('Paiements complétés','Payment completion')}</p><Link to={basePath+'/finance'} className={button+' mt-4 inline-block'}>{tr('Consulter le suivi financier','Open finance tracking')}</Link></div>:empty(tr('La synchronisation EduPay est indisponible.','EduPay synchronization unavailable.'))}</section></div></>

  const dashboard=<div className="space-y-5"><nav className="principal-tabs" aria-label={tr('Rubriques du tableau de bord','Dashboard sections')}>{([['overview',LayoutDashboard,tr('Vue d’ensemble','Overview')],['community',Users,tr('Vie de l’école','School community')]] as const).map(([key,Icon,label])=><button type="button" key={key} aria-pressed={dashboardTab===key} onClick={()=>setDashboardTab(key)}><Icon size={17}/>{label}</button>)}</nav><div hidden={dashboardTab!=='overview'} className="space-y-5">{dashboardOverview}</div><div hidden={dashboardTab!=='community'} className="principal-community"><ShiningStudentWeekWidget/><SuggestionBox/></div></div>
  const pageMeta:Record<string,[string,string,typeof Users]>={
    dashboard:[tr('Votre école, en un regard','Your school at a glance'),tr('Les priorités, les indicateurs et les accès utiles réunis dans un espace clair.','Priorities, indicators and useful shortcuts together in one clear workspace.'),LayoutDashboard],
    students:[tr('Le parcours de chaque élève','Every learner’s journey'),tr('Consultez le registre officiel et les informations de chaque élève.','Explore the official registry and each learner’s details.'),GraduationCap],
    parents:[tr('Les familles au cœur de KCS','Families at the heart of KCS'),tr('Recherchez les parents et retrouvez leurs enfants et leurs coordonnées.','Find parents, their children and contact details.'),Users],
    admissions:[tr('Accompagner les admissions','Guide every admission'),tr('Suivez les candidatures, les entretiens et vos observations pédagogiques.','Track applications, interviews and your academic review notes.'),ClipboardList],
    announcements:[tr('La vie de notre école','Our school in the loop'),tr('Retrouvez les annonces officielles et les informations importantes.','Find official announcements and important school updates.'),Megaphone],
    reports:[tr('Les rapports, avec perspective','Reports with perspective'),tr('Suivez les bulletins et les rapports pédagogiques transmis par les enseignants.','Follow report cards and academic reports submitted by teachers.'),FileText],
    'teacher-reports':[tr('Rapports des enseignants','Teacher reports'),tr('Consultez les rapports soumis et leurs documents.','Review submitted reports and their documents.'),FileText],
    'main-teachers':[tr('Les équipes de chaque classe','Every class, the right team'),tr('Organisez les responsabilités, les sections et les affectations des élèves.','Organize class leadership, sections and learner assignments.'),Users],
    'academic-calendar':[tr('Le calendrier qui nous réunit','One calendar for our school'),tr('Partagez le même calendrier officiel avec la Super Administration.','Manage the same official calendar as Super Administration.'),CalendarDays],
    finance:[tr('Une lecture claire des soldes','Balances at a glance'),tr('Consultez les informations EduPay utiles au suivi scolaire.','Review EduPay information relevant to school follow-up.'),WalletCards],
    messages:[tr('Des échanges qui font avancer','Conversations that move us forward'),tr('Consultez l’historique ou rédigez un message ciblé avec ses pièces jointes.','Search your history or compose a targeted message with attachments.'),MessageSquare],
    permissions:[tr('Vos responsabilités, en toute clarté','Your responsibilities, clearly defined'),tr('Retrouvez vos autorisations et la trace de vos actions.','Review your permissions and your activity trail.'),ShieldCheck],
    settings:[tr('Un espace qui vous ressemble','Your account, your preferences'),tr('Gérez votre profil et la sécurité de votre compte. Le calendrier dispose de son propre menu.','Manage your profile and account security. The calendar has its own menu.'),Settings],
    'report-cards':[tr('Bulletins · consultation','Report cards · consultation'),tr('Les mêmes documents officiels, en lecture seule.','The same official documents, read only.'),FileText],
    transcripts:[tr('Transcripts · consultation','Transcripts · consultation'),tr('Parcours officiel de Grade 9 à Grade 12, en lecture seule.','Official Grade 9–12 academic history, read only.'),FileText],
    'teaching-attendance':[tr('Les cours, à l’heure juste','Every lesson, on time'),tr('Suivez les séances des enseignants, les présences des élèves et vos décisions.','Review teacher sessions, learner attendance and your decisions.'),ClipboardCheck],
    attendance:[tr('Votre présence à KCS','Your attendance at KCS'),tr('Retrouvez vos présences et leur historique.','Review your attendance and its history.'),CalendarDays],
  }
  const [pageTitle,pageDescription,PageIcon]=pageMeta[segment]||pageMeta.dashboard
  const content = isAdministrator && (segment==='report-cards'||segment==='transcripts') ? <AcademicRecordsControlCenter view={segment} readOnly/> : segment === 'teaching-attendance' ? <TeachingAttendanceWorkspace manager/> : segment === 'teacher-reports' ? <TeacherActivityReportsInbox/> : segment==='attendance'?<StaffAttendanceSelf/>:segment==='main-teachers'?<AdministratorMainTeacherWorkspace/>:segment==='academic-calendar'?<AcademicCalendarSettings/>:(segment==='students'||segment==='records')?studentsView:segment==='parents'?parentsView:segment==='admissions'?admissionsView:segment==='announcements'?announcementsView:segment==='reports'?<div className="space-y-5"><nav className="principal-tabs" aria-label={tr('Rubriques des rapports','Report sections')}>{([['workflow',tr('Suivi des bulletins','Report-card review')],['teachers',tr('Rapports des enseignants','Teacher reports')]] as const).map(([key,label])=><button type="button" key={key} aria-pressed={reportTab===key} onClick={()=>setReportTab(key)}><FileText size={17}/>{label}</button>)}</nav><div hidden={reportTab!=='workflow'}>{reportsView}</div><div hidden={reportTab!=='teachers'}><TeacherActivityReportsInbox/></div></div>:segment==='finance'?financeView:segment==='messages'?messagesView:segment==='permissions'?permissionsView:segment==='settings'?<AccountSettingsPanel roleLabel={roleTitle}/>:dashboard

  return <div className="portal-shell flex"><PortalSidebar/><main data-principal-main={isAdministrator?true:undefined} className="min-h-0 min-w-0 flex-1 overflow-x-hidden overflow-y-auto"><AdministratorPortalHeader status={status}/><div data-portal-workspace data-principal-workspace className="space-y-5 p-4 sm:p-6"><header className="nexus-workspace-heading"><span className="nexus-workspace-heading-icon"><PageIcon size={25}/></span><div className="min-w-0 flex-1"><span className="nexus-workspace-kicker">KCS · {roleTitle}</span><h1>{pageTitle}</h1><p className="mt-2 max-w-3xl text-sm">{pageDescription}</p></div><button type="button" onClick={()=>void load()} disabled={status==='loading'} className="principal-refresh">{status==='loading'?tr('Actualisation…','Refreshing…'):tr('Actualiser','Refresh')}</button></header>{notice&&<p className="rounded-xl bg-kcs-blue-50 p-3 text-sm font-semibold text-kcs-blue-800">{notice}</p>}{status==='error'&&<button onClick={()=>void load()} className={button}>{tr('Réessayer la synchronisation','Retry synchronization')}</button>}{content}</div></main></div>
}
export default StaffPortal
